import {NextResponse}from'next/server';import pool from'@/lib/db';import{requireRole,unauthorized}from'@/lib/auth';import{ensureProjectManagementSchema}from'@/lib/project-management';
export async function PATCH(req,{params}){if(!requireRole(req,'admin'))return unauthorized();try{await ensureProjectManagementSchema();const b=await req.json(),id=Number((await params).id),name=String(b.name||'').trim();if(!name)return NextResponse.json({success:false,error:'Vendor name is required'},{status:400});const r=await pool.query(`UPDATE pm_vendors SET name=$1,phone=$2,trade=$3,address=$4,is_active=$5 WHERE id=$6 RETURNING *`,[name,b.phone||null,b.trade||null,b.address||null,b.is_active!==false,id]);return r.rows[0]?NextResponse.json({success:true,data:r.rows[0]}):NextResponse.json({success:false,error:'Vendor not found'},{status:404})}catch(e){return NextResponse.json({success:false,error:e.message},{status:500})}}
export async function DELETE(req,{params}){if(!requireRole(req,'admin'))return unauthorized();try{await ensureProjectManagementSchema();const id=Number((await params).id),r=await pool.query(`UPDATE pm_vendors SET is_active=FALSE WHERE id=$1 RETURNING *`,[id]);return r.rows[0]?NextResponse.json({success:true}):NextResponse.json({success:false,error:'Vendor not found'},{status:404})}catch(e){return NextResponse.json({success:false,error:e.message},{status:500})}}
